command:
$paths = @(git status --porcelain=v1 | ForEach-Object { $_.Substring(3) }) | Where-Object { $_ -eq 'CMakeLists.txt' -or $_ -like 'include/*' -or $_ -like 'src/*' -or $_ -like 'tests/*' -or $_ -eq '.forge-codex/state/decisions/P16-014-bounded-dashboard-listener-generations-and-overload-routing.md' } | Sort-Object -Unique
$strictUtf8 = [System.Text.UTF8Encoding]::new($false, $true)
$violations = [System.Collections.Generic.List[string]]::new()
foreach ($relativePath in $paths) {
    $fullPath = Join-Path (Get-Location).Path $relativePath
    $bytes = [System.IO.File]::ReadAllBytes($fullPath)
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { $violations.Add("${relativePath}: UTF-8 BOM present") }
    try { $text = $strictUtf8.GetString($bytes) } catch { $violations.Add("${relativePath}: invalid UTF-8"); continue }
    if ([regex]::IsMatch($text, '(?<!\r)\n')) { $violations.Add("${relativePath}: bare LF present") }
    if ([regex]::IsMatch($text, '\r(?!\n)')) { $violations.Add("${relativePath}: bare CR present") }
    if (-not $text.EndsWith("`r`n", [System.StringComparison]::Ordinal)) { $violations.Add("${relativePath}: missing final CRLF") }
}
if ($paths.Count -ne 35) { throw "Expected 35 checkpoint text files, found $($paths.Count)." }
if ($violations.Count -ne 0) { throw ($violations -join [Environment]::NewLine) }
Write-Output "Validated 35 checkpoint text files as UTF-8 without BOM, CRLF-only, with final CRLF."
